#include <iostream>
#include <queue>
#include <vector>

using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    if (n >= m) {
        cout << n - m << endl;
    } else {
        vector<bool> visited(m + 2, false);
        queue<pair<int, int>> q;
        q.push({n, 0});
        visited[n] = true;

        int ans = 0;
        while (!q.empty()) {
            auto current = q.front();
            q.pop();

            int location = current.first;
            int dist = current.second;

            if (location == m) {
                ans = dist;
                break;
            }

            // Multiply by 2
            if (location * 2 <= m + 1 && !visited[location * 2]) {
                q.push({location * 2, dist + 1});
                visited[location * 2] = true;
            }

            // Subtract 1
            if (location - 1 >= 0 && !visited[location - 1]) {
                q.push({location - 1, dist + 1});
                visited[location - 1] = true;
            }
        }

        cout << ans << endl;
    }

    return 0;
}

